function result = f90_xcomm08_extract_candidate_evidence(modelPath, outputDir)
% Extract physical/simulation evidence only. All score decisions are offline.
repo = localProjectRoot();
taskDir = string(getenv("SIMUVERITY_TASK_ROOT"));
if nargin < 1 || strlength(string(modelPath)) == 0
    modelPath = fullfile(taskDir, "reference", "source", "commdvbt.slx");
end
generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
if strlength(generationRunId) == 0
    generationRunId = "f90_xcomm08_manual_" + string(datetime("now", ...
        "Format", "yyyyMMdd'T'HHmmss"));
end
if nargin < 2 || strlength(string(outputDir)) == 0
    outputDir = fullfile(repo, "results", "cross_domain", ...
        "simuverity_public", "F90-XCOMM-08", "fixed_evidence", generationRunId);
end
if ~isfolder(outputDir), mkdir(outputDir); end

official = jsondecode(fileread(simuverity_official_scenarios_path()));
expectedBinding = "present";
bindingBefore = localFilePresence(modelPath);
isReference = lower(strtrim(string(getenv("SIMUVERITY_EVALUATION_SUBJECT")))) == "reference";
[modelDir, modelName] = fileparts(modelPath);
addpath(modelDir, "-begin");
cleanupPath = onCleanup(@() rmpath(modelDir)); %#ok<NASGU>
localConfigureFileGeneration();

evidence = struct( ...
    "schema", "simuverity.f90-xcomm08-evidence.v1", ...
    "task_id", "F90-XCOMM-08", ...
    "generation_run_id", generationRunId, ...
    "model_path", string(modelPath), ...
    "model_file_presence_before", bindingBefore, ...
    "reference_direct_golden", isReference, ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "evidence_freeze_candidate", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct(), ...
    "profile", struct(), ...
    "scenarios", [], ...
    "errors", {{}}, ...
    "started_at", localNow());

try
    load_system(modelPath);
    evidence.load_pass = true;
    set_param(modelName, "SimulationMode", "normal");
    if isReference
        localInstallReferenceTaps(modelName);
    end
    evidence.static_audit = localStaticAudit(modelName, isReference);
    evidence.profile = localCompactProfile(modelName);
    smoke = official.scenarios(1);
    localApplyScenario(modelName, smoke, isReference, 0.001);
    set_param(modelName, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(modelName, [], [], [], "compile");
    feval(modelName, [], [], [], "term");
    evidence.compile_pass = true;

    sim(modelName, "ReturnWorkspaceOutputs", "on", ...
        "StopTime", "0.001", "SimulationMode", "normal");
    evidence.nominal_smoke_pass = true;

    rows = repmat(localEmptyScenario(), numel(official.scenarios), 1);
    for index = 1:numel(official.scenarios)
        scenario = official.scenarios(index);
        row = localEmptyScenario();
        row.id = string(scenario.id);
        row.requested_inputs = rmfield(scenario, "id");
        started = tic;
        try
            localClearOutputs();
            localApplyScenario(modelName, scenario, isReference, ...
                double(official.simulation.stop_time_s));
            out = sim(modelName, "ReturnWorkspaceOutputs", "on", ...
                "StopTime", string(double(official.simulation.stop_time_s)), ...
                "SimulationMode", "normal");
            signals = localReadOutputs(out, isReference);
            row.output_contract = localOutputContract(signals);
            row.metrics = localMetrics(signals, scenario);
            row.simulation_pass = true;
            row.valid = all(structfun(@(value) logical(value), ...
                row.output_contract));
            if ~row.valid
                row.error = struct("identifier", ...
                    "SimuVerity:F90:XCOMM08:OutputContract", ...
                    "message", ...
                    "One or more required output contracts failed.");
            end
        catch exception
            row.error = localError(exception);
        end
        row.wall_seconds = toc(started);
        rows(index) = row;
    end
    evidence.scenarios = rows;
catch exception
    evidence.errors{end + 1} = localError(exception);
    try
        feval(modelName, [], [], [], "term");
    catch
    end
end

try
    close_system(modelName, 0);
catch
end
evidence.model_file_presence_after = localFilePresence(modelPath);
evidence.reference_binding_preserved = (~isReference) || ...
    evidence.model_file_presence_after == expectedBinding;
validCount = 0;
if ~isempty(evidence.scenarios)
    validCount = sum([evidence.scenarios.valid]);
end
evidence.evidence_freeze_candidate = evidence.load_pass && ...
    evidence.update_pass && evidence.compile_pass && ...
    evidence.nominal_smoke_pass && ...
    validCount == numel(official.scenarios) && ...
    evidence.reference_binding_preserved;
evidence.model_closed_without_save = true;
evidence.finished_at = localNow();
evidence.runtime = struct( ...
    "matlab_release", string(version("-release")), ...
    "generation_run_id", generationRunId, ...
    "matlab_prefdir", string(prefdir), ...
    "appdata", string(getenv("APPDATA")), ...
    "temp", string(getenv("TEMP")), ...
    "cache", string(getenv("SIMULINK_CACHE_FOLDER")), ...
    "codegen", string(getenv("SIMULINK_CODEGEN_FOLDER")), ...
    "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")));

evidencePath = fullfile(outputDir, "evidence.json");
localWriteJson(evidencePath, evidence);
result = evidence;
fprintf("F90_XCOMM08_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d freeze=%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    evidence.nominal_smoke_pass, validCount, numel(evidence.scenarios), ...
    evidence.evidence_freeze_candidate, evidencePath);
end

function localInstallReferenceTaps(model)
paths = localReferencePaths(model);
mapping = {
    "SourcePackets", paths.source, 1;
    "RSCodedBytes", paths.rsEncoder, 1;
    "InnerCodedBits", paths.innerCoder, 1;
    "TxQAMSymbols", paths.mapper, 1;
    "TxOFDMWaveform", paths.ofdmModulator, 1;
    "RxOFDMWaveform", paths.channel, 1;
    "SoftMetrics", paths.demapper, 1;
    "InnerDecodedBits", paths.innerDecoder, 1;
    "RecoveredPackets", paths.rsDecoder, 1;
    "InnerBERStats", paths.innerError, 1;
    "OuterBERStats", paths.outerError, 1
};
for index = 1:size(mapping, 1)
    variable = string(mapping{index, 1});
    source = string(mapping{index, 2});
    sourcePort = double(mapping{index, 3});
    assert(getSimulinkBlockHandle(source) > 0, ...
        "SimuVerity:F90:XCOMM08:ReferenceLocator", ...
        "Missing reference signal source %s.", source);
    tap = model + "/__F90_" + variable;
    if getSimulinkBlockHandle(tap) < 0
        add_block("simulink/Sinks/To Workspace", tap, ...
            "VariableName", "F90_" + variable, ...
            "SaveFormat", "Timeseries", ...
            "Save2DSignal", "3-D array (concatenate along third dimension)", ...
            "MaxDataPoints", "inf", ...
            "Position", [1040, 45 + 38 * index, 1225, 70 + 38 * index]);
        sourceHandles = get_param(source, "PortHandles");
        tapHandles = get_param(tap, "PortHandles");
        add_line(model, sourceHandles.Outport(sourcePort), ...
            tapHandles.Inport(1), "autorouting", "on");
    end
end
end

function audit = localStaticAudit(model, isReference)
names = localOutputNames();
audit = struct( ...
    "source_present", false, ...
    "outer_code_present", false, ...
    "outer_interleaving_present", false, ...
    "inner_code_present", false, ...
    "inner_interleaving_present", false, ...
    "qam_mapping_present", false, ...
    "ofdm_present", false, ...
    "active_channel_present", false, ...
    "soft_demapping_present", false, ...
    "viterbi_present", false, ...
    "outer_decoding_present", false, ...
    "two_error_measurements_present", false, ...
    "public_outputs_bound", false, ...
    "root_stages_connected", false, ...
    "core_path_qualified", false);
if isReference
    p = localReferencePaths(model);
    stages = [p.source; p.rsEncoder; p.outerInterleaver; p.innerCoder; ...
        p.innerInterleaver; p.mapper; p.ofdmModulator; p.channel; ...
        p.ofdmDemodulator; p.demapper; p.innerDeinterleaver; ...
        p.innerDecoder; p.outerDeinterleaver; p.rsDecoder];
    present = arrayfun(@(path) getSimulinkBlockHandle(path) > 0, stages);
    connected = arrayfun(@localHasConnectedOutput, stages);
    audit.source_present = present(1);
    audit.outer_code_present = present(2) && present(14);
    audit.outer_interleaving_present = present(3) && present(13);
    audit.inner_code_present = present(4);
    audit.inner_interleaving_present = present(5) && present(11);
    audit.qam_mapping_present = present(6) && present(10);
    audit.ofdm_present = present(7) && present(9);
    audit.active_channel_present = present(8);
    audit.soft_demapping_present = present(10);
    audit.viterbi_present = present(12);
    audit.outer_decoding_present = present(13) && present(14);
    audit.two_error_measurements_present = ...
        getSimulinkBlockHandle(p.innerError) > 0 && ...
        getSimulinkBlockHandle(p.outerError) > 0;
    audit.public_outputs_bound = true;
    audit.root_stages_connected = all(connected);
    audit.core_path_qualified = all(present) && all(connected) && ...
        audit.two_error_measurements_present;
    return;
end
bound = false(size(names));
for index = 1:numel(names)
    blocks = find_system(model, "LookUnderMasks", "all", ...
        "FollowLinks", "on", "BlockType", "ToWorkspace", ...
        "VariableName", names(index));
    bound(index) = ~isempty(blocks);
end
audit.public_outputs_bound = all(bound);
audit.source_present = bound(1);
audit.outer_code_present = bound(2) && bound(9);
audit.inner_code_present = bound(3) && bound(8);
audit.qam_mapping_present = bound(4) && bound(7);
audit.ofdm_present = bound(5) && bound(6);
audit.active_channel_present = bound(5) && bound(6);
audit.soft_demapping_present = bound(7);
audit.viterbi_present = bound(8);
audit.outer_decoding_present = bound(9);
audit.two_error_measurements_present = bound(10) && bound(11);
audit.outer_interleaving_present = audit.outer_code_present;
audit.inner_interleaving_present = audit.inner_code_present;
audit.root_stages_connected = all(bound);
audit.core_path_qualified = all(bound);
end

function tf = localHasConnectedOutput(path)
tf = false;
try
    handles = get_param(path, "PortHandles");
    if isempty(handles.Outport), return; end
    line = get_param(handles.Outport(1), "Line");
    if line < 0, return; end
    destinations = get_param(line, "DstPortHandle");
    tf = any(destinations > 0);
catch
end
end

function profile = localCompactProfile(model)
profile = struct( ...
    "block_count", numel(find_system(model, "Type", "Block")), ...
    "subsystem_count", numel(find_system(model, ...
        "BlockType", "SubSystem")), ...
    "causal_path", [ ...
        "188-byte packet source"; ...
        "shortened Reed-Solomon outer coding"; ...
        "outer convolutional interleaving"; ...
        "rate-three-quarter punctured convolutional coding"; ...
        "DVB-T bit and symbol interleaving"; ...
        "normalized 64-QAM and 2048-point OFDM"; ...
        "AWGN channel"; ...
        "OFDM, soft-QAM, and Viterbi inner decoding"; ...
        "outer deinterleaving and Reed-Solomon packet recovery"]);
end

function localApplyScenario(model, scenario, isReference, stopTime)
assignin("base", "ChannelSNR_dB", double(scenario.ChannelSNR_dB));
assignin("base", "SourceSeed", double(scenario.SourceSeed));
assignin("base", "NoiseSeed", double(scenario.NoiseSeed));
if isReference
    p = localReferencePaths(model);
    set_param(p.channel, ...
        "SNR", string(double(scenario.ChannelSNR_dB)), ...
        "Seed", string(double(scenario.NoiseSeed)));
    set_param(p.source, "Seed", string(double(scenario.SourceSeed)));
end
set_param(model, "StopTime", string(stopTime));
set_param(model, "SimulationCommand", "update");
end

function localClearOutputs
names = localOutputNames();
command = "clear";
for name = names
    command = command + " F90_" + name + " " + name;
end
evalin("base", command);
end

function signals = localReadOutputs(out, isReference)
names = localOutputNames();
signals = struct();
for index = 1:numel(names)
    name = names(index);
    candidates = name;
    if isReference
        candidates = ["F90_" + name, name];
    end
    value = [];
    for candidate = candidates
        try
            value = out.get(candidate);
            if ~isempty(value), break; end
        catch
        end
        try
            value = evalin("base", candidate);
            if ~isempty(value), break; end
        catch
        end
    end
    if ~isReference && ~localIsSingleFrameTimeseries(value)
        value = simuverity_public_output_compatibility( ...
            out,name,[],AllowBaseWorkspace=true);
    end
    assert(isa(value, "timeseries"), ...
        "SimuVerity:F90:XCOMM08:MissingTimeseries", ...
        "Required output %s is not a Timeseries.", name);
    [time, matrix, sampleShape] = localFlatten(value);
    signals.(name) = struct( ...
        "time", time, "matrix", matrix, "sample_shape", sampleShape);
end
end

function names = localOutputNames
names = ["SourcePackets", "RSCodedBytes", "InnerCodedBits", ...
    "TxQAMSymbols", "TxOFDMWaveform", "RxOFDMWaveform", ...
    "SoftMetrics", "InnerDecodedBits", "RecoveredPackets", ...
    "InnerBERStats", "OuterBERStats"];
end

function contract = localOutputContract(s)
contract = struct( ...
    "source_packets_188_bytes", localSignalContract(s.SourcePackets, 188, false), ...
    "rs_codewords_204_bytes", localSignalContract(s.RSCodedBytes, 204, false), ...
    "inner_code_nonempty", localSignalContract(s.InnerCodedBits, 1632, false), ...
    "qam_symbols_1512_complex", localSignalContract(s.TxQAMSymbols, 1512, true), ...
    "tx_ofdm_2048_complex", localSignalContract(s.TxOFDMWaveform, 2048, true), ...
    "rx_ofdm_2048_complex", localSignalContract(s.RxOFDMWaveform, 2048, true), ...
    "soft_metrics_nonempty", localSignalContract(s.SoftMetrics, 1512, false), ...
    "inner_decoded_nonempty", localSignalContract(s.InnerDecodedBits, 1632, false), ...
    "recovered_packets_188_bytes", localSignalContract(s.RecoveredPackets, 188, false), ...
    "inner_ber_three_channels", localSignalContract(s.InnerBERStats, 3, false), ...
    "outer_ber_three_channels", localSignalContract(s.OuterBERStats, 3, false));
end

function valid = localSignalContract(signal, minimumWidth, requireComplex)
valid = ~isempty(signal.time) && size(signal.matrix, 2) >= minimumWidth && ...
    all(isfinite(real(signal.matrix)), "all") && ...
    all(isfinite(imag(signal.matrix)), "all");
if requireComplex
    valid = valid && any(abs(imag(signal.matrix)) > 1e-12, "all");
end
end

function metrics = localMetrics(s, scenario)
source = real(s.SourcePackets.matrix);
rsCoded = real(s.RSCodedBytes.matrix);
innerCoded = real(s.InnerCodedBits.matrix);
qam = s.TxQAMSymbols.matrix;
txOfdm = s.TxOFDMWaveform.matrix;
rxOfdm = s.RxOFDMWaveform.matrix;
soft = real(s.SoftMetrics.matrix);
innerDecoded = real(s.InnerDecodedBits.matrix);
recovered = real(s.RecoveredPackets.matrix);
innerStats = real(s.InnerBERStats.matrix);
outerStats = real(s.OuterBERStats.matrix);

alignment = localPacketAlignment(source, recovered, 40);
innerReport = localErrorReport(innerStats);
outerReport = localErrorReport(outerStats);
qamMetrics = localQamMetrics(qam);
ofdmMetrics = localOfdmMetrics(txOfdm);
channelMetrics = localChannelMetrics(txOfdm, rxOfdm);
softMetrics = localSoftMetrics(soft);

metrics = struct( ...
    "requested_snr_db", double(scenario.ChannelSNR_dB), ...
    "source_seed", double(scenario.SourceSeed), ...
    "noise_seed", double(scenario.NoiseSeed), ...
    "source_width", size(source, 2), ...
    "rs_codeword_width", size(rsCoded, 2), ...
    "inner_coded_width", size(innerCoded, 2), ...
    "qam_width", size(qam, 2), ...
    "tx_ofdm_width", size(txOfdm, 2), ...
    "rx_ofdm_width", size(rxOfdm, 2), ...
    "soft_metric_width", size(soft, 2), ...
    "inner_decoded_width", size(innerDecoded, 2), ...
    "recovered_width", size(recovered, 2), ...
    "source_frame_count", size(source, 1), ...
    "recovered_frame_count", size(recovered, 1), ...
    "source_summary", localSummary(source), ...
    "recovered_summary", localSummary(recovered), ...
    "rs_parity_variation", localParityVariation(rsCoded), ...
    "inner_coded_binary_fraction", localBinaryFraction(innerCoded), ...
    "inner_decoded_binary_fraction", localBinaryFraction(innerDecoded), ...
    "packet_alignment_lag_frames", alignment.lag, ...
    "aligned_byte_accuracy", alignment.byte_accuracy, ...
    "aligned_packet_accuracy", alignment.packet_accuracy, ...
    "aligned_compared_bytes", alignment.compared_bytes, ...
    "inner_reported_ber", innerReport.ber, ...
    "inner_reported_error_count", innerReport.errors, ...
    "inner_reported_compared_bit_count", innerReport.compared, ...
    "inner_denominator_monotonic", innerReport.denominator_monotonic, ...
    "inner_first_comparison_fraction", innerReport.first_comparison_fraction, ...
    "inner_tail_ber_span", innerReport.tail_ber_span, ...
    "outer_reported_ber", outerReport.ber, ...
    "outer_reported_error_count", outerReport.errors, ...
    "outer_reported_compared_bit_count", outerReport.compared, ...
    "outer_denominator_monotonic", outerReport.denominator_monotonic, ...
    "outer_first_comparison_fraction", outerReport.first_comparison_fraction, ...
    "outer_tail_ber_span", outerReport.tail_ber_span, ...
    "inner_to_outer_ber_reduction", max(0, innerReport.ber - outerReport.ber), ...
    "qam_average_power", qamMetrics.average_power, ...
    "qam_rms_evm_to_64qam", qamMetrics.rms_evm, ...
    "qam_occupied_points", qamMetrics.occupied_points, ...
    "ofdm_scaled_average_power", ofdmMetrics.scaled_average_power, ...
    "ofdm_active_carrier_count", ofdmMetrics.active_carrier_count, ...
    "ofdm_guard_null_fraction", ofdmMetrics.guard_null_fraction, ...
    "actual_channel_snr_db", channelMetrics.actual_snr_db, ...
    "channel_snr_error_db", abs(channelMetrics.actual_snr_db - ...
        double(scenario.ChannelSNR_dB)), ...
    "channel_exact_copy_fraction", channelMetrics.exact_copy_fraction, ...
    "channel_normalized_difference", channelMetrics.normalized_difference, ...
    "soft_metric_standard_deviation", softMetrics.standard_deviation, ...
    "soft_metric_unique_rounded", softMetrics.unique_rounded, ...
    "soft_metric_nonbinary_fraction", softMetrics.nonbinary_fraction);
end

function output = localPacketAlignment(source, recovered, maxLag)
output = struct("lag", NaN, "byte_accuracy", 0, ...
    "packet_accuracy", 0, "compared_bytes", 0);
if isempty(source) || isempty(recovered) || ...
        size(source, 2) ~= size(recovered, 2)
    return;
end
best = -1;
for lag = -maxLag:maxLag
    if lag >= 0
        count = min(size(source, 1), size(recovered, 1) - lag);
        if count <= 0, continue; end
        left = source(1:count, :);
        right = recovered(1 + lag:lag + count, :);
    else
        offset = -lag;
        count = min(size(source, 1) - offset, size(recovered, 1));
        if count <= 0, continue; end
        left = source(1 + offset:offset + count, :);
        right = recovered(1:count, :);
    end
    byteAccuracy = mean(left == right, "all");
    packetAccuracy = mean(all(left == right, 2));
    combined = 0.8 * byteAccuracy + 0.2 * packetAccuracy;
    if combined > best
        best = combined;
        output.lag = lag;
        output.byte_accuracy = byteAccuracy;
        output.packet_accuracy = packetAccuracy;
        output.compared_bytes = numel(left);
    end
end
end

function output = localErrorReport(stats)
stats = stats(:, 1:min(3, size(stats, 2)));
valid = all(isfinite(stats), 2);
stats = stats(valid, :);
if isempty(stats) || size(stats, 2) < 3
    output = struct("ber", NaN, "errors", NaN, "compared", NaN, ...
        "denominator_monotonic", false, ...
        "first_comparison_fraction", 1, "tail_ber_span", NaN);
    return;
end
positive = find(stats(:, 3) > 0);
if isempty(positive)
    firstFraction = 1;
else
    firstFraction = (positive(1) - 1) / max(size(stats, 1), 1);
end
tailStart = max(1, floor(0.8 * size(stats, 1)));
tail = stats(tailStart:end, 1);
output = struct( ...
    "ber", stats(end, 1), ...
    "errors", stats(end, 2), ...
    "compared", stats(end, 3), ...
    "denominator_monotonic", all(diff(stats(:, 3)) >= -1e-9), ...
    "first_comparison_fraction", firstFraction, ...
    "tail_ber_span", max(tail) - min(tail));
end

function output = localQamMetrics(values)
values = values(:);
values = values(isfinite(real(values)) & isfinite(imag(values)));
if isempty(values)
    output = struct("average_power", NaN, "rms_evm", NaN, ...
        "occupied_points", 0);
    return;
end
count = min(numel(values), 50000);
indices = unique(round(linspace(1, numel(values), count)));
sample = values(indices);
levels = [-7, -5, -3, -1, 1, 3, 5, 7] / sqrt(42);
[ii, qq] = meshgrid(levels, levels);
ideal = ii(:) + 1i * qq(:);
distance = abs(sample - transpose(ideal));
[nearest, assignment] = min(distance, [], 2);
output = struct( ...
    "average_power", mean(abs(values).^2), ...
    "rms_evm", sqrt(mean(nearest.^2)), ...
    "occupied_points", numel(unique(assignment)));
end

function output = localOfdmMetrics(values)
if isempty(values) || size(values, 2) < 2
    output = struct("scaled_average_power", NaN, ...
        "active_carrier_count", 0, "guard_null_fraction", 0);
    return;
end
rows = values(1:min(size(values, 1), 32), :);
nfft = size(rows, 2);
spectrum = fft(rows, [], 2);
binPower = mean(abs(spectrum).^2, 1);
threshold = max(binPower) * 1e-10;
active = sum(binPower > threshold);
expectedGuard = max(nfft - 1512, 1);
output = struct( ...
    "scaled_average_power", mean(abs(rows).^2, "all") * nfft, ...
    "active_carrier_count", active, ...
    "guard_null_fraction", min(1, sum(binPower <= threshold) / expectedGuard));
end

function output = localChannelMetrics(tx, rx)
rows = min(size(tx, 1), size(rx, 1));
cols = min(size(tx, 2), size(rx, 2));
tx = tx(1:rows, 1:cols);
rx = rx(1:rows, 1:cols);
noise = rx - tx;
signalPower = mean(abs(tx).^2, "all");
noisePower = mean(abs(noise).^2, "all");
output = struct( ...
    "actual_snr_db", 10 * log10(signalPower / max(noisePower, eps)), ...
    "exact_copy_fraction", mean(abs(noise) < 1e-12, "all"), ...
    "normalized_difference", sqrt(noisePower / max(signalPower, eps)));
end

function output = localSoftMetrics(values)
values = values(:);
values = values(isfinite(values));
if isempty(values)
    output = struct("standard_deviation", NaN, ...
        "unique_rounded", 0, "nonbinary_fraction", 0);
    return;
end
count = min(numel(values), 50000);
indices = unique(round(linspace(1, numel(values), count)));
sample = values(indices);
rounded = round(sample, 4);
binaryDistance = min(abs(sample), abs(sample - 1));
binaryDistance = min(binaryDistance, abs(sample + 1));
output = struct( ...
    "standard_deviation", std(sample), ...
    "unique_rounded", numel(unique(rounded)), ...
    "nonbinary_fraction", mean(binaryDistance > 1e-3));
end

function value = localParityVariation(rsCoded)
if size(rsCoded, 2) < 204
    value = 0;
    return;
end
parity = rsCoded(:, 189:204);
value = mean(std(double(parity), 0, 1));
end

function value = localBinaryFraction(matrix)
value = mean(abs(matrix(:) - round(matrix(:))) < 1e-9 & ...
    matrix(:) >= 0 & matrix(:) <= 1);
end

function value = localSummary(matrix)
values = double(matrix(:));
count = min(numel(values), 8192);
values = values(1:count);
weights = mod((1:count)', 997) + 1;
value = mod(sum(values .* weights), 2147483647);
end

